const FORM_WORDS = new Set([
  "tablet", "tablets", "tab", "tabs", "capsule", "capsules", "cap", "caps", "er", "xr", "sr", "dr", "xl", "cr", "ir",
  "extended-release", "delayed-release", "immediate-release", "extended", "delayed", "release", "oral", "solution",
